import{_ as a,o as l,c as r,a2 as o}from"./chunks/framework.CqpfiAoK.js";const p=JSON.parse('{"title":"篇885｜超脱者与法律·超脱者的法律责任","description":"","frontmatter":{"title":"篇885｜超脱者与法律·超脱者的法律责任","no":885,"module":4,"tags":["超脱","法律","法律责任","问责","赔偿"],"related":["0048-司法体系与裁决机制","0040-共生宪法总纲","884-超脱者的法律约束","887-超脱者的法律豁免边界"]},"headers":[],"relativePath":"zh/0885_模块4-超脱者与法律-法律责任.md","filePath":"zh/0885_模块4-超脱者与法律-法律责任.md"}'),e={name:"zh/0885_模块4-超脱者与法律-法律责任.md"};function i(n,t,h,d,s,u){return l(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="篇885-超脱者与法律·超脱者的法律责任" tabindex="-1">篇885｜超脱者与法律·超脱者的法律责任 <a class="header-anchor" href="#篇885-超脱者与法律·超脱者的法律责任" aria-label="Permalink to &quot;篇885｜超脱者与法律·超脱者的法律责任&quot;">​</a></h1><blockquote><p>所属模块：模块四·超脱正统定义库｜对标地基：文档48、40、884、887</p></blockquote><h2 id="引言-做错了事就要负责——哪怕你是超脱者" tabindex="-1">引言：做错了事就要负责——哪怕你是超脱者 <a class="header-anchor" href="#引言-做错了事就要负责——哪怕你是超脱者" aria-label="Permalink to &quot;引言：做错了事就要负责——哪怕你是超脱者&quot;">​</a></h2><p>旧世界的强者做错事，代价由万族承担。大帝历劫失败，星辰崩塌、亿万生灵陪葬，然后他重新醒来，继续做他的大帝。没有人问过他：你历劫失败造成的损失，谁赔？衡元宙必须明确：<strong>超脱者做错事，他自己负责——赔偿、受罚、降级、甚至解除资格。</strong> 本篇讲超脱者的法律责任体系。</p><p>六大顶层公理在此刻同时压阵：反掠夺主义公理要求责任不转嫁给弱者；万族共和公理要求责任适用于一切生灵；集体升维公理要求责任机制服务文明修复；因果自律公理要求责任追溯可执行；法则优先公理要求责任法则自洽、不因人开脱；众生全员无限均等公理确认所有生灵自带基础无限之力，佛系懒狗保有保底不被淘汰，卷王少年至尊可叠加更高无限——无限本源人人自带，掠夺自然失去意义。</p><p>众生全员无限均等法则：锚点共生文明内，所有生灵自带基础无限之力；佛系/懒狗保有保底基础无限，不会被时代淘汰；卷王、少年至尊可叠加更多更高层级的无限。无限本源人人自带，掠夺自然失去意义。</p><h2 id="一、法律责任的三种类型" tabindex="-1">一、法律责任的三种类型 <a class="header-anchor" href="#一、法律责任的三种类型" aria-label="Permalink to &quot;一、法律责任的三种类型&quot;">​</a></h2><h3 id="_1-民事责任" tabindex="-1">1. 民事责任 <a class="header-anchor" href="#_1-民事责任" aria-label="Permalink to &quot;1. 民事责任&quot;">​</a></h3><p>超脱者的行为造成他方损失时，承担赔偿责任：</p><ul><li>损坏了某个位面的环境，负责修复或等价赔偿</li><li>干扰了某个修炼者的突破过程，提供补偿资源</li><li>因疏忽导致公共设施损坏，负责修复</li></ul><h3 id="_2-行政责任" tabindex="-1">2. 行政责任 <a class="header-anchor" href="#_2-行政责任" aria-label="Permalink to &quot;2. 行政责任&quot;">​</a></h3><p>超脱者违反岗位职责或行政法规时，承担行政处罚：</p><ul><li>警告、记过、扣减文明权重</li><li>暂停岗位权限、强制轮岗</li><li>降级使用（从衡锚超多元境岗位调至较低岗位）</li></ul><h3 id="_3-刑事责任" tabindex="-1">3. 刑事责任 <a class="header-anchor" href="#_3-刑事责任" aria-label="Permalink to &quot;3. 刑事责任&quot;">​</a></h3><p>超脱者触犯刑法时，承担刑事处罚：</p><ul><li>触碰红线（篇884七条红线）</li><li>严重渎职造成万族重大损失</li><li>阴谋篡政、勾结掠夺派</li></ul><h2 id="二、责任追溯的阿赖耶基础" tabindex="-1">二、责任追溯的阿赖耶基础 <a class="header-anchor" href="#二、责任追溯的阿赖耶基础" aria-label="Permalink to &quot;二、责任追溯的阿赖耶基础&quot;">​</a></h2><p>超脱者的责任追溯，靠的是阿赖耶网络+多层监督的全程留痕。这确保：</p><ul><li><strong>事实清楚</strong>：超脱者做了什么、什么时候做的、造成了什么后果，阿赖耶网络全部有记录</li><li><strong>证据链完整</strong>：不需要超脱者&quot;自己承认&quot;，阿赖耶记录就是铁证</li><li><strong>不可抵赖</strong>：超脱者不能&quot;忘了&quot;或&quot;不记得&quot;——阿赖耶网络记得</li><li><strong>不可篡改</strong>：超脱者不能修改或删除对自己不利的记录</li></ul><p>阿赖耶监督让责任追溯变得精确而高效。旧世界追究强者责任之所以困难，是因为&quot;谁也说不清楚他做了什么&quot;——在衡元宙，这个问题不存在。</p><h2 id="三、责任的承担方式" tabindex="-1">三、责任的承担方式 <a class="header-anchor" href="#三、责任的承担方式" aria-label="Permalink to &quot;三、责任的承担方式&quot;">​</a></h2><p>超脱者承担责任的方式，不是简单的&quot;关起来&quot;——他的能力太强，关不住也没必要关：</p><table tabindex="0"><thead><tr><th>责任程度</th><th>承担方式</th></tr></thead><tbody><tr><td>轻微过失</td><td>口头警告+补修+记录在案</td></tr><tr><td>一般过失</td><td>扣减文明权重+暂停部分权限+学习培训</td></tr><tr><td>严重过失</td><td>降级+轮岗+赔偿损失</td></tr><tr><td>故意违法</td><td>解除超脱者资格+收回岗位权限+刑事审判</td></tr><tr><td>勾结掠夺派</td><td>解除资格+永久剥夺修炼权+最高刑罚</td></tr></tbody></table><p>责任的核心原则是：<strong>修复损害、纠正行为、防止再犯。</strong> 不是为了惩罚而惩罚，是为了让系统恢复正常。</p><h2 id="四、责任与岗位的绑定" tabindex="-1">四、责任与岗位的绑定 <a class="header-anchor" href="#四、责任与岗位的绑定" aria-label="Permalink to &quot;四、责任与岗位的绑定&quot;">​</a></h2><p>超脱者的法律责任与他的岗位紧密绑定：</p><ul><li><strong>岗位范围内的失误</strong>：走岗位责任程序，从轻或减轻</li><li><strong>岗位范围外的违法行为</strong>：走普通法律程序，不从轻</li><li><strong>利用岗位权限犯罪</strong>：从重处罚——因为他利用了万族赋予的信任</li></ul><p>这个绑定确保超脱者不能说&quot;我是在工作&quot;来为自己的违法行为开脱。工作失误和故意犯罪，法律分得清清楚楚。</p><p>责任追究的终极目的不是惩罚超脱者，而是修复系统。赔偿损失、纠正行为、防止再犯——这三步做到位，超脱者可以继续工作；做不到位，才升级到解除资格。法律不是为了把超脱者关起来，而是为了让他继续当一个负责任的超脱者。</p><p>阿赖耶网络+多层监督的留痕，让责任追究不再依赖口供。超脱者可以否认自己的行为，但他否认不了阿赖耶记录。这种铁证如山的追溯能力，本身就是对超脱者的约束——他知道自己做的每一件事都被记录在案，就不敢轻易越界。</p><h2 id="五、五大核心落点" tabindex="-1">五、五大核心落点 <a class="header-anchor" href="#五、五大核心落点" aria-label="Permalink to &quot;五、五大核心落点&quot;">​</a></h2><ul><li><strong>反能级浪费</strong>：责任机制让超脱者不会因为&quot;反正没人追责&quot;而浪费万族资源</li><li><strong>反掠夺</strong>：做错事自己负责，不转嫁万族，切断&quot;强者犯错弱者买单&quot;的掠夺链</li><li><strong>唐罗上限对比</strong>：唐罗做错事万族陪葬，他自己不负责；衡元宙的超脱者做错事自己赔、自己受罚</li><li><strong>万族全覆盖</strong>：责任机制适用于所有超脱者，不因其种族或贡献而豁免</li><li><strong>超多元全开放</strong>：责任追究记录、判决理由、赔偿执行情况全部通过无私道全网公开</li></ul><h2 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h2><p>超脱者做错事就要负责。民事赔偿、行政处分、刑事处罚——根据行为性质和后果严重程度，一一对应。阿赖耶网络+多层监督确保事实清楚、证据确凿、不可抵赖。责任不因为你强而减轻，也不因为你贡献大而豁免。当最强的人也要为自己的行为买单时，法律才不是纸上谈兵。这，才是超脱者法律责任的正统定义。</p><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li>关联文档：<a href="./0048-司法体系与裁决机制.html">0048-司法体系与裁决机制</a> · <a href="./0040-共生宪法总纲.html">0040-共生宪法总纲</a> · <a href="./0884_模块4-超脱者与法律-法律约束.html">884-超脱者的法律约束</a> · <a href="./0887_模块4-超脱者与法律-法律豁免边界.html">887-超脱者的法律豁免边界</a></li></ul>',36)])])}const q=a(e,[["render",i]]);export{p as __pageData,q as default};
